#!/data/data/com.termux/files/usr/bin/bash
storage_analysis(){ header; record_usage "Analisis Storage"; local target; target=$(ask "Folder yang dianalisis" "${HOME}/storage/shared"); [[ -d "$target" ]] || { err "Folder tidak ditemukan"; pause; return; }; echo "File terbesar:"; find "$target" -type f -printf '%s\t%p\n' 2>/dev/null | sort -nr | head -20 | awk '{printf "%8.2f MB  %s\n",$1/1024/1024,$2}'; echo; echo "Folder terbesar:"; du -h -d 1 "$target" 2>/dev/null | sort -hr | head -20; pause; }
clean_storage(){ header; record_usage "Pembersih Storage"; local target; target=$(ask "Folder target" "${HOME}/storage/shared"); [[ -d "$target" ]] || { err "Folder tidak ditemukan"; pause; return; }; echo "Membersihkan cache/temp/empty folder di $target"; find "$target" -type f \( -name '*.tmp' -o -name '*.temp' -o -name '*.log' -o -name 'thumbs.db' \) -print -delete 2>/dev/null; find "$target" -type d -empty -print -delete 2>/dev/null; ok "Selesai"; pause; }
